ontinue; //not masked\n\t\t\t\t}\n\n\t\t\t\tvec3 uv_local = (decals.data[decal_index].xform * vec4(vertex, 1.0)).xyz;\n\t\t\t\tif (any(lessThan(uv_local, vec3(0.0, -1.0, 0.0))) || any(greaterThan(uv_local, vec3(1.0)))) {\n\t\t\t\t\tcontinue; //out of decal\n\t\t\t\t}\n\n\t\t\t\tfloat fade = pow(1.0 - (uv_local.y > 0.0 ? uv_local.y : -uv_local.y), uv_local.y > 0.0 ? decals.data[decal_index].upper_fade : decals.data[decal_index].lower_fade);\n\n\t\t\t\tif (decals.data[decal_index].normal_fade > 0.0) {\n\t\t\t\t\tfade *= smoothstep(decals.data[decal_index].normal_fade, 1.0, dot(geo_normal, decals.data[decal_index].normal) * 0.5 + 0.5);\n\t\t\t\t}\n\n\t\t\t\t//we need ddx/ddy for mipmaps, so simulate them\n\t\t\t\tvec2 ddx = (decals.data[decal_index].xform * vec4(vertex_ddx, 0.0)).xz;\n\t\t\t\tvec2 ddy = (decals.data[decal_index].xform * vec4(vertex_ddy, 0.0)).xz;\n\n\t\t\t\tif (decals.data[decal_index].albedo_rect != vec4(0.0)) {\n\t\t\t\t\t//has albedo\n\t\t\t\t\tvec4 decal_albedo;\n\t\t\t\t\tif (sc_decal_use_mipmaps()) {\n\t\t\t\t\t\tdecal_albedo = textureGrad(sampler2D(decal_atlas_srgb, decal_sampler), uv_local.xz * decals.data[decal_index].albedo_rect.zw + decals.data[decal_index].albedo_rect.xy, ddx * decals.data[decal_index].albedo_rect.zw, ddy * decals.data[decal_index].albedo_rect.zw);\n\t\t\t\t\t} else {\n\t\t\t\t\t\tdecal_albedo = textureLod(sampler2D(decal_atlas_srgb, decal_sampler), uv_local.xz * decals.data[decal_index].albedo_rect.zw + decals.data[decal_index].albedo_rect.xy, 0.0);\n\t\t\t\t\t}\n\t\t\t\t\tdecal_albedo *= decals.data[decal_index].modulate;\n\t\t\t\t\tdecal_albedo.a *= fade;\n\t\t\t\t\talbedo = mix(albedo, decal_albedo.rgb, decal_albedo.a * decals.data[decal_index].albedo_mix);\n\n\t\t\t\t\tif (decals.data[decal_index].normal_rect != vec4(0.0)) {\n\t\t\t\t\t\tvec3 decal_normal;\n\t\t\t\t\t\tif (sc_decal_use_mipmaps()) {\n\t\t\t\t\t\t\tdecal_normal = textureGrad(sampler2D(decal_atlas, decal_sampler), uv_local.xz * decals.data[decal_index].no